namespace Demo.Pricing
{
    public class DiscountCalculator
    {
        public decimal Apply(decimal total, int units)
        {
            if (units <= 0) return total;
            return units > 100 ? total * 0.90m : total;
        }

        public decimal ApplyTiered(decimal total, int units)
        {
            if (units > 500) return total * 0.80m;
            if (units > 200) return total * 0.85m;
            return Apply(total, units);
        }
    }
}

