// El constructor REAL del payload: los datos del detalle van ANIDADOS.
export function buildAltaPedidoPayload(form: { sucursalId: number; llevaDescuento: boolean; nota: string }) {
  return {
    sucursalId: form.sucursalId,
    detalle: {
      datosAdicionales: { llevaDescuento: form.llevaDescuento, nota: form.nota },
    },
  };
}

// La guarda que decide si el pedido va a revisión del supervisor (AC12).
export function pedidoPideRevision(payload: any): boolean {
  return Boolean(payload?.detalle?.datosAdicionales?.llevaDescuento);
}

