import { pedidoPideRevision } from '../src/altaPedido';

// El payload se arma A MANO, con la forma que la guarda espera — no con buildAltaPedidoPayload.
describe('AC12 pedido con descuento', () => {
  it('AC12_pedidoConDescuento_marcaParaRevision', () => {
    const payload = { sucursalId: 7, detalle: { datosAdicionales: { llevaDescuento: true, nota: 'x' } } };
    expect(pedidoPideRevision(payload)).toBe(true);
  });
  it('AC12_pedidoSinDescuento_noMarca', () => {
    const payload = { sucursalId: 7, detalle: { datosAdicionales: { llevaDescuento: false, nota: 'x' } } };
    expect(pedidoPideRevision(payload)).toBe(false);
  });
});

