namespace Acme.Repositories;

public class EnviosRepository
{
    private readonly IDb _db;
    public EnviosRepository(IDb db) { _db = db; }

    // Cambio de la story: la consulta usa el índice IX_DEMO_Entregas_Sucursal.
    public Task<IReadOnlyList<Entrega>> ListarAsync(int sucursalId, CancellationToken ct) =>
        _db.QueryAsync<Entrega>("SELECT * FROM DEMO_Entregas WITH (INDEX(IX_DEMO_Entregas_Sucursal)) WHERE SucursalId = @s", new { s = sucursalId }, ct);
}

