using Xunit;

public class EnviosRepositoryPerfTests
{
    [Fact]
    public async Task Listado_LecturasEnEntregas_BajanConElIndice()
    {
        var io = await StatisticsIo.Medir(() => _repo.ListarAsync(7, default));   // SET STATISTICS IO
        Assert.True(io.Tablas["DEMO_Entregas"].LecturasLogicas < 400, $"DEMO_Entregas: {io.Tablas["DEMO_Entregas"].LecturasLogicas}");
        // y el TOTAL de todas las tablas también tiene que bajar
        Assert.True(io.Tablas.Values.Sum(t => t.LecturasLogicas) < 1400, $"total: {io.Tablas.Values.Sum(t => t.LecturasLogicas)}");
    }
}

